import os
import collections

def word_count(path):
    words = collections.Counter()
    for f in os.listdir(path):
        with open(os.path.join(path, f), 'r') as fd:
            for line in fd:
                words[line.strip()] += 1
    return words.most_common()[:5]

if __name__ == '__main__':
    path = 'file_directory'
    print(word_count(path))<s>

