import os
import collections

def word_counts(directory):
    word_counts = collections.Counter()
    for filename in os.listdir(directory):
        with open(os.path.join(directory, filename), 'r') as f:
            for line in f:
                words = line.split()
                word_counts[words[0]] += 1

    top_words = sorted(word_counts.most_common(5), key=word_counts.get)
    return top_words

if __name__ == '__main__':
    print(word_counts('.'))<s>

