def majority_element(arr):
    # Initialize the majority variable to -1
    majority = -1

    # Iterate through the array
    for i in range(len(arr)):
        # If the majority is -1, set it to the current element
        if majority == -1:
            majority = arr[i]

        # If the majority is not the same as the current element, update the majority
        elif arr[i] != majority:
            majority = arr[i]

    # Return the majority
    return majority<s>

